function rate_limit(string $scope, int $limit): void
{
    $minute = intdiv(time(), 60);
    $ip = (string) ($_SERVER['REMOTE_ADDR'] ?? 'unknown');
    $bucket = hash('sha256', $scope . '|' . $ip . '|' . (string) ($_POST['phone'] ?? ''));
    $q = db()->prepare('INSERT INTO rate_limits (bucket,window_start,hits) VALUES (?,?,1) ON DUPLICATE KEY UPDATE hits=hits+1');
    $q->execute([$bucket, $minute]);
    $q = db()->prepare('SELECT hits FROM rate_limits WHERE bucket=? AND window_start=?');
    $q->execute([$bucket, $minute]);
    if ((int) $q->fetchColumn() > $limit) { http_response_code(429); exit('ส่งคำขอบ่อยเกินไป กรุณารอสักครู่แล้วลองใหม่'); }
}

function track_page_view(string $pageKey): void
{
    try { db()->prepare('INSERT INTO page_view_stats (view_date,page_key,views) VALUES (?,?,1) ON DUPLICATE KEY UPDATE views=views+1')->execute([date('Y-m-d'),$pageKey]); } catch (Throwable) { /* Stats must not interrupt a public page. */ }
}

function form_input(string $name, string $label, string $type = 'text', array $extra = []): string
{
    $attrs = '';
    foreach ($extra as $key => $value) $attrs .= ' ' . e($key) . '="' . e($value) . '"';
    return '<div class="col-md-6"><label class="form-label required" for="' . e($name) . '">' . e($label) . '</label><input class="form-control" id="' . e($name) . '" name="' . e($name) . '" type="' . e($type) . '" required' . $attrs . '></div>';
}

function current_event(): array
{
